'use strict';

const os = require('os');
const yandexLogger = require('../../src');
const jsonStream = require('../../streams/json');

describe('YandexLogger. Streams. Json', () => {
    let logger;
    let stream;
    let jestFakeTimers;

    beforeEach(() => {
        // Initialize a mock function to replace `write`.
        stream = { write: jest.fn() };

        logger = yandexLogger({
            streams: [
                {
                    stream: jsonStream({ stream }),
                },
            ],
        });

        // Use fake timers
        jestFakeTimers = jest.useFakeTimers('modern');
        jest.setSystemTime(1000);
    });

    afterEach(() => {
        // Clear fake timers
        jestFakeTimers.clearAllTimers();
    });

    it('должен логировать записи в формате json в переданный стрим', () => {
        logger.info('message');

        expect(stream.write).toHaveBeenCalledWith(JSON.stringify({
            pid: process.pid,
            date: '1970-01-01T00:00:01.000Z',
            hostname: os.hostname(),
            level: 30,
            levelName: 'INFO',
            msgFormat: 'message',
            msgArgs: [],
            msg: 'message',
            name: 'yandex-logger',
        }) + '\n');
        expect(stream.write).toHaveBeenCalledTimes(1);
    });

    it('должен логировать циклические записи', () => {
        let circularObj = {};
        circularObj.circularRef = circularObj;
        circularObj.list = [circularObj, circularObj];

        logger.info({ circularObj }, 'message');

        expect(stream.write).toHaveBeenCalledWith(JSON.stringify({
            pid: process.pid,
            date: '1970-01-01T00:00:01.000Z',
            hostname: os.hostname(),
            level: 30,
            levelName: 'INFO',
            circularObj: {
                circularRef: '[Circular ~.circularObj]',
                list: [
                    '[Circular ~.circularObj]',
                    '[Circular ~.circularObj]',
                ],
            },
            msgFormat: 'message',
            msgArgs: [],
            msg: 'message',
            name: 'yandex-logger',
        }) + '\n');
        expect(stream.write).toHaveBeenCalledTimes(1);
    });
});
